# Define a simple Node class for a linked list
Node <- setRefClass("Node",
  fields = c("value" = "numeric", "next" = "NULL"),
  methods = list(
    initialize = function(value, next) {
      .self$value <- value
      .self$next <- next
    },
    get_value = function() {
      return(.self$value)
    },
    get_next = function() {
      return(.self$next)
    }
  )
)

# Function to return the node at a specific index in a linked list
get_node_at_index <- function(head, index) {
  current_node <- head
  current_index <- 0

  while (current_node != NULL && current_index < index) {
    current_node <- current_node$next
    current_index <- current_index + 1
  }

  return(current_node)
}

# Example usage:
# Create a linked list: 1 -> 2 -> 3 -> 4
node1 <- Node$new(1, NULL)
node2 <- Node$new(2, NULL)
node3 <- Node$new(3, NULL)
node4 <- Node$new(4, NULL)

node1$next <- node2
node2$next <- node3
node3$next <- node4

# Get the node at index 2 (should return Node containing value 3)
result_node <- get_node_at_index(node1, 2)
print(result_node$get_value())  # Output should be 3
```
