class ZooRecord:
    def __init__(self):
        self.animals = {}

    def add_animal(self, name, species):
        if species not in self.animals:
            self.animals[species] = []
        self.animals[species].append(name)

    def remove_animal(self, name, species):
        if species in self.animals and name in self.animals[species]:
            self.animals[species].remove(name)
            if not self.animals[species]:
                del self.animals[species]

    def get_animals(self, species=None):
        if species:
            return self.animals.get(species, [])
        return self.animals

