#include <iostream>
#include <vector>

void printPaths(std::vector<std::vector<int>>& matrix, std::vector<std::string>& paths, int x, int y, int m, int n, std::string path) {
    if (x == m - 1 && y == n - 1) {
        paths.push_back(path);
        return;
    }

    if (x < m) {
        printPaths(matrix, paths, x + 1, y, m, n, path + 'D'); // Down
    }
    if (y < n) {
        printPaths(matrix, paths, x, y + 1, m, n, path + 'R'); // Right
    }
}

std::vector<std::string> findAllPaths(int m, int n) {
    std::vector<std::string> paths;
    printPaths({}, paths, 0, 0, m, n, "");
    return paths;
}

int main() {
    int m = 3, n = 3; // Define the size of the matrix
    auto paths = findAllPaths(m, n);
    for (const auto& path : paths) {
        std::cout << path << std::endl;
    }
    return 0;
}
```

