Here’s how you can modify the code to include the nth element in an iterative manner:

```c
#include <stdio.h>

int Fibonacci(int n) {
    if (n <= 1) {
        return n;
    }

    int prev = 0, curr = 1, next;

    for (int i = 2; i <= n; i++) {
        next = prev + curr;
        prev = curr;
        curr = next;
    }

    return curr;
}

int main() {
